package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the generate-periods form from the body; its dates are checked once the sheet (and its today) is loaded. */
public class ValidateGeneratePeriods {
    public void validate(@RequestBody GeneratePeriodsRequest request, Out<GeneratePeriodsRequest> body) {
        body.set(request == null ? new GeneratePeriodsRequest(null, null) : request);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds a period per calendar month from the from-date's month to the to-date's, each from the first to the last
 *  day of its month and named yyyy-mm, leaving out a month whose name the sheet already has or whose days overlap
 *  a period; refuses a date that is not a calendar date and a to-date before the from-date. */
public class GeneratePeriods {
    public void generate(@Val GeneratePeriodsRequest request, @Val Sheet sheet, PeriodRepository repository,
            Out<GeneratedPeriods> generatedOut) throws InvalidPeriodException {
        LocalDate today = sheet.getToday() != null ? sheet.getToday() : LocalDate.now();
        LocalDate from = date(request.from(), "from", today);
        LocalDate to = date(request.to(), "to", today);
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date must be on or after the from-date.");
        }
        generatedOut.set(months(sheet, YearMonth.from(from), YearMonth.from(to), repository));
    }

    /** Adds a period per calendar month from the first month to the last, leaving out a month whose name the sheet
     *  already has or whose days overlap a period. */
    static GeneratedPeriods months(Sheet sheet, YearMonth firstMonth, YearMonth lastMonth, PeriodRepository repository) {
        List<Period> periods = new ArrayList<>(repository.findBySheetIdOrderByFromDateAscIdAsc(sheet.getId()));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = firstMonth; !month.isAfter(lastMonth); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
                continue;
            }
            Period period = repository.saveAndFlush(new Period(sheet.getId(), name, first, last));
            periods.add(period);
            made.add(period);
        }
        return new GeneratedPeriods(made);
    }

    private static LocalDate date(String value, String which, LocalDate today) throws InvalidPeriodException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return today;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a calendar date.");
        }
    }
}
package net.officefloor.hq.app.period;

/** The generate-periods form as submitted: a from and a to date (YYYY-MM-DD), either blank for the sheet's today. */
public record GeneratePeriodsRequest(String from, String to) {
}
package net.officefloor.hq.app.period;

import java.util.List;

/** The periods a generate made, in month order. */
public record GeneratedPeriods(List<Period> periods) {
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records each period a generate made, in month order, as an added period. */
public class AuditPeriodsGenerated {
    public void audit(@Val GeneratedPeriods generated, @RequestHeader(name = "X-User", required = false) String user,
            Audit audit) {
        for (Period period : generated.periods()) {
            audit.record("PERIOD_ADDED sheet=" + period.getSheetId() + " by=" + AuditUser.decode(user)
                    + " period=" + period.getName() + " from=" + period.getFromDate() + " to=" + period.getToDate());
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGeneratedPeriods {
    public record Generated(int generated) {
    }

    public void respond(@Val GeneratedPeriods generated, ObjectResponse<Generated> response) {
        response.send(new Generated(generated.periods().size()));
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the fiscal year's twelve monthly periods, from its first month (the sheet's fiscal year start month of the
 *  year) on, exactly as the period generator does. */
public class GenerateFiscalYear {
    public void generate(@Val GenerateFiscalYearRequest request, @Val Sheet sheet, PeriodRepository repository,
            Out<GeneratedPeriods> generatedOut) {
        YearMonth first = YearMonth.of(Integer.parseInt(request.year()), sheet.getFiscalStartMonth());
        generatedOut.set(GeneratePeriods.months(sheet, first, first.plusMonths(11), repository));
    }
}
package net.officefloor.hq.app.period;

import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the generate-fiscal-year form from the body; refuses a year that is not four digits. */
public class ValidateGenerateFiscalYear {

    private static final Pattern YEAR = Pattern.compile("\\d{4}");

    public void validate(@RequestBody GenerateFiscalYearRequest request, Out<GenerateFiscalYearRequest> body)
            throws InvalidPeriodException {
        String year = request == null || request.year() == null ? "" : request.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidPeriodException("The fiscal year must be a year (yyyy).");
        }
        body.set(new GenerateFiscalYearRequest(year));
    }
}
package net.officefloor.hq.app.period;

/** The generate-fiscal-year form as submitted: the fiscal year (yyyy), named by the calendar year its first day falls in. */
public record GenerateFiscalYearRequest(String year) {
}
